def extract(fp,i):
    t=open(fp).read().replace('\\n','\n')
    m=re.search(f'Demo pair {i} input \\((\\d+)x(\\d+)\\)',t)
    hm,wm=int(m[1]),int(m[2])
    # find start of message text after header: next non-whitespace block = grid lines until blank line or other header
    idx=t.index('Demo pair %d input %dx%d'%(i,hm,wm))
    body=t[idx+2:]
    lines=[]
    for line in body.split('\n'):
        if len(line)==wm and all(x.isdigit() for x in line):
            lines.append([int(x) for x in line.split()])
        else:
            break
    return lines
