                idx=m.end()
                lines=[l.split() for l in tt[idx:].split('\n') if l.split()]
                n=len(lines)
                ok=all(len(l)==w and all(x.isdigit() for x in l) for l in lines[:h])
                if ok:
                    rows=[[int(x) for x in l] for l in lines[:h]]
                    if f'Demo pair {num} input' not in G:
                        G[f'Demo pair {num} input']=rows
        outpairs=[]
        for m in re.finditer(r'Demo pair (\d+) output \((\d+)x(\d+)\)',tt):
            num,h,w=int(m.group(1)),int(m.group(2)),int(m.group(3))
            idx=m.end(); lines=[l.split() for l in tt[idx:].split('\n') if l.split()]
            ok=all(len(l)==w and all(x.isdigit() for x in l) for l in lines[:h])
            if ok:
                outpairs.append((num,[[int(x) for x in l] for l in lines[:h]]))
        if len(pairs)>=6 and set(map(lambda t:t[0],outpairs))==set(pairs):
            for n,o in outpairs:
                G.setdefault(f'Demo pair {n} output',o)
    return G
