import numpy as np
from collections import Counter
def f_demo(inp, paint='elbow'):
    ii=np.array(inp); h,w=ii.shape
    bg=Counter(ii.flatten()).most_common(1)[0][0]
    out=ii.copy()
    cells_all={(y,x) for y in range(h) for x in range(w) if ii[y][x]!=bg}
    colors={p:int(ii[p[0]][p[1]]) for p in cells_all}
    for (y,x) in list(cells_all):
        nb=[(a,b) for a,b in [(y-1,x),(y+1,x),(x-1,y),(x+1,y)] if (a,b) in cells_all]
        if len(nb)==2:
            dirs=[((y-a),(x-b)) for a,b in nb]
            step=((dirs[0][0]>0)-(dirs[0][0]<0), (dirs[0][1]>0)-(dirs[0][1]<0))
            r,c=y+step[0],x+step[1]
            while 0<=r<h and 0<=c<w and out[r][c]==bg:
                out[r][c]=colors.get((y,x),out[y][x])
                r+=step[0]; c+=step[1]
    return out.tolist()
